CREATE OR REPLACE PROCEDURE sp(para_Major IN NUMBER, para_Sex IN VARCHAR2, para_ResTypeID IN NUMBER, para_ResTypeName IN VARCHAR2, para_Rating IN NUMBER) IS CURSOR c2 IS SELECT "ResTypeID", "ResTypeName" FROM "Restaurant_Type" WHERE "ResTypeID" > para_ResTypeID AND "ResTypeName" LIKE para_ResTypeName FOR UPDATE;
CURSOR c3 IS SELECT "Rating" FROM "Restaurant" WHERE "Rating" BETWEEN para_Rating AND para_Rating * 2;
CURSOR c4 IS SELECT "Major", "Sex" FROM "Student" WHERE "Major" > TRUNC(para_Major / 2);
rec2 c2 % ROWTYPE;
rec3 c3 % ROWTYPE;
rec4 c4 % ROWTYPE;
temp_num NUMBER(10);
temp_text VARCHAR2(4000);
row_count NUMBER(10);
flag NUMBER(10);
BEGIN
    temp_num := 0;
    temp_text := '';
    row_count := 0;
    flag := 0;
    IF para_Major < 10 THEN
        UPDATE "Student" SET "Sex" = 'INACTIVE' WHERE "Major" < para_Major;
        flag := 1;
    ELSIF para_Major < 25 THEN
        OPEN c2;
        flag := 2;
    ELSIF para_Major < 40 THEN
        OPEN c3;
        flag := 3;
    ELSE
        OPEN c4;
        flag := 4;
    END IF;
    IF flag = 2 OR flag = 3 OR flag = 4 THEN
        IF flag = 2 THEN
            LOOP
                FETCH c2 INTO rec2;
                EXIT WHEN c2 % NOTFOUND;
                row_count := ROUND(row_count + 1);
                IF rec2."ResTypeID" < 50 THEN
                    UPDATE "Restaurant_Type" SET "ResTypeName" = 'COMPLETED' WHERE CURRENT OF c2;
                END IF;
            END LOOP;
            CLOSE c2;
        ELSIF flag = 3 THEN
            LOOP
                FETCH c3 INTO rec3;
                EXIT WHEN c3 % NOTFOUND;
                row_count := ROUND(row_count + 1);
                IF rec3."Rating" > 100 THEN
                    temp_text := 'OVER_LIMIT';
                ELSIF rec3."Rating" > 50 THEN
                    temp_text := 'WITHIN_RANGE';
                ELSE
                    temp_text := 'BELOW_MIN';
                END IF;
            END LOOP;
            CLOSE c3;
        ELSIF flag = 4 THEN
            LOOP
                FETCH c4 INTO rec4;
                EXIT WHEN c4 % NOTFOUND;
                row_count := ROUND(row_count + 1);
            END LOOP;
            CLOSE c4;
        END IF;
    END IF;
    IF flag = 1 THEN
        DELETE FROM "Restaurant_Type" WHERE "ResTypeID" < para_ResTypeID;
    ELSIF flag = 2 AND temp_num > 100 THEN
        UPDATE "Restaurant" SET "Rating" = "Rating" - 10 WHERE "Rating" > 200;
    ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
        DELETE FROM "Restaurant" WHERE "Rating" > 150;
    ELSIF flag = 4 AND temp_num > 5 THEN
        UPDATE "Student" SET "Sex" = 'PROCESSED' WHERE "Major" < para_Major;
    ELSE
        UPDATE "Restaurant_Type" SET "ResTypeName" = 'DEFAULT' WHERE "ResTypeID" IS NULL;
    END IF;
END sp;
